import {giftContentPages} from './experience.js';
// Runs both in the application and inside the self-contained gift HTML.
export async function mountPortableGift(data,createBook){
 const make=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=text;return el;};
 const root=make('main','portable-reader');root.innerHTML='<header class="portable-top"><a href="#" class="portable-brand">capimimo.</a><button type="button" class="portable-large" aria-pressed="false">Ler com letra maior</button></header><section class="portable-intro"><p>Um presente preparado com carinho</p><h1></h1><p class="portable-from"></p></section><section class="portable-unwrapping"><canvas width="600" height="600" role="img" aria-label="Animação de abertura do presente"></canvas><button type="button" class="portable-start button primary">Abrir meu presente</button><button type="button" class="portable-skip" hidden>Pular animação</button></section><section class="portable-content" hidden><div class="portable-event" hidden></div><div class="portable-object" aria-label="Visualização 3D do presente"></div><p class="portable-render-status" role="status"></p><div class="portable-tools"><button type="button" data-action="minus">− Reduzir</button><button type="button" data-action="fit">Ajustar à tela</button><button type="button" data-action="plus">＋ Ampliar</button><button type="button" data-action="cover">Ver capa</button></div><nav class="portable-pages" aria-label="Páginas do livro"><button type="button" data-action="previous">← Anterior</button><output></output><button type="button" data-action="next">Próxima →</button></nav><div class="portable-photos" aria-label="Fotos do presente"></div><details class="portable-reading" open><summary>Ler a mensagem</summary><h2></h2><p></p></details><button type="button" class="portable-sound">Ouvir o áudio</button><div class="portable-chapters"></div><section class="portable-rsvp" hidden></section><p class="portable-note">Este arquivo guarda o presente no seu aparelho. Uma resposta baixada precisa ser enviada por você a quem criou o mimo.</p></section>';document.body.replaceChildren(root);document.body.classList.add('portable-body');if(window.parent!==window)document.body.classList.add('embedded');
 const $=s=>root.querySelector(s);$('.portable-intro h1').textContent=data.format==='convite'?data.recipient||'Você está convidado':('Para '+(data.storyDesign?.nickname||data.recipient||'você'));$('.portable-from').textContent=data.experience?.sender?'De '+data.experience.sender:'';
 let reader=null,index=0,opened=true,zoom=1,selectedPhoto=data.photo,started=false,raf=0,disposed=false,sound=null,sounding=false,soundPending=false,soundRequest=0,pageBusy=false,readerPreparing=false,fallback=false;const pages=giftContentPages(data),object=$('.portable-object'),renderStatus=$('.portable-render-status');
 const viewData=(at=index)=>({...data,...pages[at],photo:at>0||data.format==='livro'?pages[at].photo:selectedPhoto,pageTitle:pages[at].title,theme:data.theme||{sheet:'classic',row:0,label:'Um mimo'}});
 const fallbackGallery=make('div','portable-fallback-gallery');fallbackGallery.hidden=true;fallbackGallery.setAttribute('aria-label','Fotos do presente');$('.portable-reading').before(fallbackGallery);
 function renderFallback(){if(!fallback)return;const current=viewData(),sources=data.format==='livro'?[{src:current.photo||pages[index]?.photo,caption:current.pageTitle}]:[{src:current.photo||pages[index]?.photo},...(data.photos||[])];const seen=new Set();fallbackGallery.replaceChildren();for(const photo of sources){if(!photo.src||seen.has(photo.src))continue;seen.add(photo.src);const figure=make('figure'),image=make('img','portable-fallback-photo');image.src=photo.src;image.alt=photo.caption||photo.name||'Foto deste presente';figure.append(image);if(photo.caption)figure.append(make('figcaption','',photo.caption));fallbackGallery.append(figure);}fallbackGallery.hidden=!seen.size;}
 function update(){root.querySelectorAll('.portable-tools button').forEach(button=>button.disabled=readerPreparing);const current=viewData();renderFallback();$('.portable-reading h2').textContent=current.pageTitle||data.recipient||'Feito para você';$('.portable-reading p').textContent=current.message||'Que bom ter você na minha história.';$('.portable-pages').hidden=data.format!=='livro'||pages.length<2;$('.portable-pages output').textContent=(index+1)+' de '+pages.length;$('[data-action=previous]').disabled=readerPreparing||pageBusy||index===0;$('[data-action=next]').disabled=readerPreparing||pageBusy||index===pages.length-1;$('[data-action=cover]').textContent=opened?'Ver capa':'Abrir meu presente';$('[data-action=plus]').disabled=readerPreparing||zoom>=2.2;$('[data-action=minus]').disabled=readerPreparing||zoom<=1;}
 async function reveal(){if(started||disposed)return;started=true;readerPreparing=true;object.setAttribute('aria-busy','true');cancelAnimationFrame(raf);$('.portable-unwrapping').hidden=true;$('.portable-content').hidden=false;update();renderStatus.textContent='Preparando sua visualização… Você já pode ler a mensagem abaixo.';try{const created=await createBook(object,viewData());if(disposed){created.destroy();return;}reader=created;reader.open(opened);reader.zoom(zoom);reader.motion(matchMedia('(prefers-reduced-motion: reduce)').matches);renderStatus.textContent='Use os botões para ampliar e ler. A mensagem também está disponível abaixo.';}catch{if(disposed)return;object.hidden=true;$('.portable-tools').hidden=true;renderStatus.textContent='Seu aparelho não iniciou o 3D. As fotos e a mensagem continuam disponíveis abaixo.';fallback=true;renderFallback();}finally{if(!disposed){readerPreparing=false;object.setAttribute('aria-busy','false');update();}}}

 const atlas=new Image();atlas.src=data.openingAssetUrl||data.portableAssets?.['assets/gift-opening-30fps.webp']||'';const canvas=$('.portable-unwrapping canvas'),ctx=canvas.getContext('2d');function draw(frame){ctx.clearRect(0,0,600,600);if(atlas.naturalWidth)ctx.drawImage(atlas,frame%10*320,Math.floor(frame/10)*320,320,320,0,0,600,600);canvas.dataset.frame=String(frame);}atlas.decode().then(()=>draw(0)).catch(()=>{canvas.hidden=true;});
 $('.portable-start').addEventListener('click',()=>{if(started)return;$('.portable-start').hidden=true;$('.portable-skip').hidden=false;if(matchMedia('(prefers-reduced-motion: reduce)').matches||!atlas.naturalWidth){reveal();return;}let start=null,last=-1;const tick=time=>{if(disposed||started)return;if(start===null)start=time;const frame=Math.min(89,Math.floor((time-start)*30/1000));if(frame!==last){draw(frame);last=frame;}if(frame===89)reveal();else raf=requestAnimationFrame(tick);};raf=requestAnimationFrame(tick);});$('.portable-skip').addEventListener('click',reveal);
 root.querySelectorAll('[data-action]').forEach(button=>button.addEventListener('click',async()=>{if(disposed||readerPreparing)return;const action=button.dataset.action;if(action==='next'||action==='previous'){if(pageBusy)return;const delta=action==='next'?1:-1,next=Math.max(0,Math.min(pages.length-1,index+delta));if(next===index)return;pageBusy=true;update();try{const ok=reader?await reader.turn(viewData(next),delta):true;if(ok!==false){index=next;opened=true;reader?.open(true);}}finally{pageBusy=false;}}else if(action==='cover'){opened=!opened;reader?.open(opened);}else{if(action==='fit')reader?.resetView();zoom=action==='fit'?1:Math.max(1,Math.min(2.2,zoom+(action==='plus'?.2:-.2)));reader?.zoom(zoom);}update();}));
 if(data.format==='stories')for(const photo of data.photos||[]){const button=make('button'),image=make('img');button.type='button';button.setAttribute('aria-label','Ver '+(photo.caption||photo.name||'foto'));image.src=photo.src;image.alt='';button.append(image);button.addEventListener('click',()=>{selectedPhoto=photo.src;reader?.set(viewData());});$('.portable-photos').append(button);}
 function awaitRevealReading(){if(disposed)return;reveal();const reading=$('.portable-reading');reading.open=true;reading.setAttribute('tabindex','-1');reading.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});reading.focus({preventScroll:true});}

 $('.portable-large').addEventListener('click',()=>{const large=root.classList.toggle('large-reading');$('.portable-large').textContent=large?'Letra normal':'Ler com letra maior';$('.portable-large').setAttribute('aria-pressed',String(large));if(large){awaitRevealReading();}});
 if(data.format==='convite'){
  const event=$('.portable-event');event.hidden=false;const heading=make('h2','','Vamos celebrar?'),when=make('p'),where=make('p');const valid=/^\d{4}-\d{2}-\d{2}$/.test(data.eventDate||'');when.textContent=valid?new Date(data.eventDate+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'}):'Data a combinar';where.textContent=data.eventPlace||'Local a combinar';event.append(heading,when,where);if(data.eventPlace){const map=make('a','','Ver local no mapa ↗');map.href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(data.eventPlace);map.target='_blank';map.rel='noopener noreferrer';event.append(map);}if(valid){const calendar=make('button','','Guardar data no calendário');calendar.type='button';calendar.addEventListener('click',()=>{const day=data.eventDate.replaceAll('-',''),next=new Date(data.eventDate+'T12:00:00Z');next.setUTCDate(next.getUTCDate()+1);const end=next.toISOString().slice(0,10).replaceAll('-','');const safe=value=>String(value||'').replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const ics=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Capimimo//Convite//PT-BR','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@capimimo.local','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART;VALUE=DATE:'+day,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+safe(data.recipient||'Uma celebração'),'LOCATION:'+safe(data.eventPlace),'DESCRIPTION:'+safe(data.message),'END:VEVENT','END:VCALENDAR'].join('\r\n');downloadFile('convite-capimimo.ics',new Blob([ics],{type:'text/calendar;charset=utf-8'}));});event.append(calendar);}
  const rsvp=$('.portable-rsvp');rsvp.hidden=window.parent!==window;rsvp.innerHTML='<h2>Você vem celebrar?</h2><p>Baixe sua confirmação e devolva o arquivo para quem convidou você.</p><form><label>Seu nome<input name="name" maxlength="80" required></label><label>Resposta<select name="answer"><option value="accepted">Vou participar</option><option value="declined">Não poderei ir</option></select></label><label>Pessoas ao todo<select name="count"></select></label><button class="button primary" type="submit">Baixar minha confirmação</button><p role="status"></p></form>';const form=rsvp.querySelector('form'),guest=data.guestPreview;form.elements.name.value=guest?.name||'';form.elements.name.readOnly=!!guest;for(let n=1;n<=(guest?.allowedCount||1);n++)form.elements.count.add(new Option(String(n),String(n)));form.elements.answer.addEventListener('change',()=>form.elements.count.disabled=form.elements.answer.value==='declined');form.addEventListener('submit',event=>{event.preventDefault();const reply={type:'capimimo-rsvp',giftId:data.draftId,guestId:guest?.id||'',name:form.elements.name.value.trim(),status:form.elements.answer.value,count:form.elements.answer.value==='declined'?0:Number(form.elements.count.value),createdAt:new Date().toISOString()};downloadFile('confirmacao-capimimo.json',new Blob([JSON.stringify(reply,null,2)],{type:'application/json'}));form.querySelector('[role=status]').textContent='Confirmação baixada. Envie o arquivo para quem está organizando a celebração.';});
 }
 const ex=data.experience||{};$('.portable-sound').textContent=ex.audioKind==='music'?'Ouvir a música':'Ouvir o áudio';$('.portable-sound').hidden=!['file','musicbox'].includes(ex.sound)||ex.sound==='file'&&!data.audioUrl;function renderAudio(){const button=$('.portable-sound');button.textContent=soundPending?'Cancelar carregamento':sounding?'Pausar áudio':ex.audioKind==='music'?'Ouvir a música':'Ouvir o áudio';button.setAttribute('aria-busy',String(soundPending));button.setAttribute('aria-pressed',String(sounding));}renderAudio();$('.portable-sound').addEventListener('click',async()=>{if(disposed)return;if(sounding||soundPending){soundRequest++;sound?.pause();soundPending=false;sounding=false;renderAudio();return;}const request=++soundRequest;if(!sound){const player=createSound(ex,data.audioUrl,{onEnded:()=>{if(disposed||sound!==player)return;soundRequest++;soundPending=false;sounding=false;renderAudio();}});sound=player;}const player=sound,current=()=>!disposed&&sound===player&&request===soundRequest;soundPending=true;renderAudio();try{const playing=await player.play();if(!current())return;soundPending=false;sounding=playing;renderAudio();if(!playing)$('.portable-sound').textContent='Áudio indisponível';}catch{if(!current())return;soundPending=false;sounding=false;renderAudio();$('.portable-sound').textContent='Áudio indisponível';}});if(ex.sound==='link'&&ex.musicUrl){const link=make('a','portable-music-link','Ouvir a música escolhida ↗');link.href=ex.musicUrl;link.target='_blank';link.rel='noopener noreferrer';$('.portable-sound').after(link);}
 const cleanup=createExperienceChapters($('.portable-chapters'),data);addEventListener('pagehide',()=>{disposed=true;soundRequest++;cancelAnimationFrame(raf);reader?.destroy();sound?.stop();cleanup();},{once:true});
 window.__portableGift={getState:()=>({format:data.format,index,pages:pages.length,opened,zoom,started,renderer:reader?'three':'reading',book:reader?.snapshot()})};if(window.parent!==window)window.parent.postMessage({type:'capimimo:ready'},'*');return {reveal};
}
